    92    static vector<vector<FT_Byte>>
    93    parse_data( const uint8_t*  data,
    94                size_t          size )
    95    {
    96      struct archive_entry*    entry;
    97      int                      r;
    98      vector<vector<FT_Byte>>  files;
    99
   100      unique_ptr<struct  archive,
   101                 decltype ( archive_read_free )*>  a( archive_read_new(),
   102                                                      archive_read_free );
   103
   104      // activate reading of uncompressed tar archives
   105      archive_read_support_format_tar( a.get() );
   106
   107      // the need for `const_cast' was removed with libarchive commit be4d4dd
   108      if ( !( r = archive_read_open_memory(
   109                    a.get(),
   110                    const_cast<void*>(static_cast<const void*>( data ) ),
   111                    size ) ) )
   112      {
   113        unique_ptr<struct  archive,
   114                   decltype ( archive_read_close )*>  a_open( a.get(),
   115                                                              archive_read_close );
   116
   117        // read files contained in archive
   118        for (;;)
   119        {
   120          r = archive_read_next_header( a_open.get(), &entry );
   121          if ( r == ARCHIVE_EOF )
   122            break;
   123          if ( r != ARCHIVE_OK )
   124            break;
   125
   126          vector<FT_Byte>  entry_data;
   127          r = archive_read_entry_data( a.get(), &entry_data );
   128          if ( r != ARCHIVE_OK )
   129            break;
   130
   131          files.push_back( move( entry_data ) );
   132        }
   133      }
   134
   135      if ( files.size() == 0 )
   136        files.emplace_back( data, data + size );
   137
   138      return files;
   139    }
