   142    static void
   143    setIntermediateAxis( FT_Face  face )
   144    {
   145      // only handle Multiple Masters and GX variation fonts
   146      if ( !FT_HAS_MULTIPLE_MASTERS( face ) )
   147        return;
   148
   149      // get variation data for current instance
   150      FT_MM_Var*  variations_ptr = nullptr;
   151      if ( FT_Get_MM_Var( face, &variations_ptr ) )
   152        return;
   153
   154      unique_ptr<FT_MM_Var,
   155                 decltype ( free )*>  variations( variations_ptr, free );
   156      vector<FT_Fixed>                coords( variations->num_axis );
   157
   158      // select an arbitrary instance
   159      for ( unsigned int  i = 0; i < variations->num_axis; i++ )
   160        coords[i] = ( variations->axis[i].minimum +
   161                      variations->axis[i].def     ) / 2;
   162
   163      if ( FT_Set_Var_Design_Coordinates( face,
   164                                          FT_UInt( coords.size() ),
   165                                          coords.data() ) )
   166        return;
   167    }
