   170    // the interface function to the libFuzzer library
   171    extern "C" int
   172    LLVMFuzzerTestOneInput( const uint8_t*  data,
   173                            size_t          size_ )
   174    {
   175      assert( !InitResult );
   176
   177      if ( size_ < 1 )
   178        return 0;
   179
   180      const vector<vector<FT_Byte>>&  files = parse_data( data, size_ );
   181
   182      FT_Face         face;
   183      FT_Int32        load_flags  = FT_LOAD_DEFAULT;
   184  #if 0
   185      FT_Render_Mode  render_mode = FT_RENDER_MODE_NORMAL;
   186  #endif
   187
   188      // We use a conservative approach here, at the cost of calling
   189      // `FT_New_Face' quite often.  The idea is that the fuzzer should be
   190      // able to try all faces and named instances of a font, expecting that
   191      // some faces don't work for various reasons, e.g., a broken subfont, or
   192      // an unsupported NFNT bitmap font in a Mac dfont resource that holds
   193      // more than a single font.
   194
   195      // get number of faces
   196      if ( FT_New_Memory_Face( library,
   197                               files[0].data(),
   198                               (FT_Long)files[0].size(),
   199                               -1,
   200                               &face ) )
   201        return 0;
   202      long  num_faces = face->num_faces;
   203      FT_Done_Face( face );
   204
   205      // loop over all faces
   206      for ( long  face_index = 0;
   207            face_index < num_faces;
   208            face_index++ )
